(function(){const form=document.getElementById("quoteForm");if(!form)return;const steps=[...form.querySelectorAll(".q-step")];const dots=[...form.querySelectorAll(".q-progress li")];const status=document.getElementById("quoteStatus");const done=document.getElementById("quoteDone");let current=0;let sending=false;form.classList.add("is-stepped");function show(i){current=i;steps.forEach((s,n)=>{s.hidden=n!==i;});dots.forEach((d,n)=>{d.classList.toggle("on",n<=i);});const first=steps[i].querySelector("input:not([type=hidden]), select, textarea");if(first&&i>0)first.focus({preventScroll:true});form.scrollIntoView({behavior:"smooth",block:"start"});}
function valid(step){for(const el of step.querySelectorAll("input, select, textarea")){if(!el.checkValidity()){el.reportValidity();return false;}}
return true;}
form.addEventListener("click",(e)=>{if(e.target.closest("[data-next]")){if(valid(steps[current]))show(current+1);}
if(e.target.closest("[data-back]"))show(current-1);});form.addEventListener("keydown",(e)=>{if(e.key==="Enter"&&e.target.tagName!=="TEXTAREA"&&current<steps.length-1){e.preventDefault();if(valid(steps[current]))show(current+1);}});form.addEventListener("submit",async(e)=>{e.preventDefault();if(sending)return;if(form.querySelector('[name="_honey"]').value)return;for(const s of steps){if(!valid(s)){show(steps.indexOf(s));return;}}
const btn=form.querySelector('button[type="submit"]');const label=btn.innerHTML;sending=true;btn.disabled=true;btn.classList.add("is-loading");btn.textContent="Sending…";try{const res=await fetch(form.dataset.endpoint,{method:"POST",body:new FormData(form),headers:{Accept:"application/json"}});if(!res.ok)throw new Error("send failed");steps.forEach((s)=>{s.hidden=true;});form.querySelector(".q-progress").hidden=true;done.hidden=false;done.scrollIntoView({behavior:"smooth",block:"center"});}catch(err){status.className="form-status err";status.textContent="Couldn't send right now. Please email us at arraysingenieria@gmail.com.";}finally{sending=false;btn.disabled=false;btn.classList.remove("is-loading");btn.innerHTML=label;}});show(0);window.scrollTo(0,0);})();